mapper.select:
select quantity from fin_stock_position
where tenant_id = #{tenantId} and dept_id = #{deptId} and product_id = #{productId}
for update

mapper.update:
update fin_stock_position
set quantity = #{quantity}
where tenant_id = #{tenantId} and dept_id = #{deptId} and product_id = #{productId}

mapper.select:
select coalesce(sum(change_quantity), 0)
from fin_stock_ledger
where tenant_id = #{tenantId}
  and reference_type = #{referenceType}
  and reference_id = #{referenceId}
  and product_id = #{productId}
  and del_flag = '0'

select distinct product_id
from fin_stock_ledger
where tenant_id = #{tenantId}
  and reference_type = #{referenceType}
  and reference_id = #{referenceId}
  and del_flag = '0'

select *
from fin_stock_ledger
where tenant_id = #{tenantId}
  and idempotency_key = #{idempotencyKey}
  and del_flag = '0'
limit 1

select coalesce(sum(case when change_type in ('PURCHASE_IN', 'SALE_REVERSE') then change_quantity else 0 end), 0) as in_quantity,
       coalesce(sum(case when change_type in ('SALE_OUT', 'PURCHASE_REVERSE') then -change_quantity else 0 end), 0) as out_quantity
from fin_stock_ledger
where tenant_id = #{tenantId}
  and dept_id = #{deptId}
  and product_id = #{productId}
  and del_flag = '0'
  and create_time >= #{snapshotDate}
  and create_time < date_add(#{snapshotDate}, interval 1 day)

select * from fin_stock_ledger
 where tenant_id = #{tenantId} and dept_id = #{deptId} and product_id = #{productId}
   and del_flag = '0' and create_time >= #{snapshotDate}
   and create_time < date_add(#{snapshotDate}, interval 1 day)
 order by create_time, ledger_id limit 1

select * from fin_stock_ledger
 where tenant_id = #{tenantId} and dept_id = #{deptId} and product_id = #{productId}
   and del_flag = '0' and create_time < #{snapshotDate}
 order by create_time desc, ledger_id desc limit 1

select unit_cost
from fin_stock_ledger
where tenant_id = #{tenantId}
  and reference_type = 'SALE'
  and reference_id = #{referenceId}
  and product_id = #{productId}
  and change_type = 'SALE_OUT'
  and del_flag = '0'
order by ledger_id desc
limit 1

mapper.update:
update fin_stock_ledger
  set unit_cost = #{unitCost}
where ledger_id = #{ledgerId}
  and del_flag = '0'

mapper.select:
select count(*) from fin_stock_ledger
where tenant_id = #{tenantId}
  and reference_no = #{referenceNo}
  and del_flag = '0'

select coalesce(sum(change_quantity), 0)
from fin_stock_ledger
where tenant_id = #{tenantId}
  and dept_id = #{deptId}
  and product_id = #{productId}
  and create_time >= #{freezeTime}
  and del_flag = '0'

select count(*)
from fin_stock_ledger
where tenant_id = #{tenantId}
  and dept_id = #{deptId}
  and product_id = #{productId}
  and create_time >= #{afterTime}
  and del_flag = '0'
  and change_type not in ('STOCK_TAKE_GAIN', 'STOCK_TAKE_LOSS', 'STOCK_TAKE_REVERSE')
